+package com.example;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.*;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @BeforeEach void open() { navigate(ContactView.class); }
+    TextField name() { return $(TextField.class).withLabel("Name").single(); }
+    TextField phone() { return $(TextField.class).withLabel("Phone").single(); }
+    EmailField email() { return $(EmailField.class).single(); }
+    TextArea message() { return $(TextArea.class).single(); }
+    Button button(String text) { return $(Button.class).withText(text).single(); }
+    void send() { test(button("Send")).click(); }
+    int rows() { return $(Grid.class).single().getListDataView().getItemCount(); }
+
+    @Test void validatesAllFieldsAndPreservesInput() {
+        assertTrue(button("Send").isEnabled());
+        send();
+        assertEquals("Name is required", name().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertTrue(email().isInvalid());
+        assertTrue(message().isInvalid());
+        name().setValue("Ada");
+        email().setValue("bad-address");
+        phone().setValue("1234");
+        message().setValue("x".repeat(501));
+        send();
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals("Ada", name().getValue());
+        assertEquals(501, message().getValue().length());
+        assertEquals(0, rows());
+        assertFalse($(Notification.class).exists());
+        assertTrue(button("Send").isEnabled());
+    }
+
+    @Test void sendsWithPhoneAndEmailAndKeepsNewestFirstAcrossNavigation() {
+        name().setValue("First");
+        phone().setValue("1234");
+        message().setValue("x".repeat(500));
+        send();
+        assertEquals(1, rows());
+        assertFalse(button("Send").isEnabled());
+        assertTrue(name().isEmpty() && phone().isEmpty() && email().isEmpty() && message().isEmpty());
+        assertTrue($(Notification.class).exists());
+        name().setValue("Second");
+        assertTrue(button("Send").isEnabled());
+        email().setValue("person@example.com");
+        message().setValue("Second message");
+        fireShortcut(Key.ENTER);
+        assertEquals(2, rows());
+        assertFalse(button("Send").isEnabled());
+        test($(RouterLink.class).single()).click();
+        assertFalse($(Dialog.class).exists());
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+        assertEquals(2, rows());
+        var first = (SentMessages.Message) $(Grid.class).single().getListDataView().getItem(0);
+        assertEquals("Second", first.name());
+    }
+
+    @Test void guardsNavigationAndCanCancelThenDiscard() {
+        phone().setValue("draft");
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened());
+        test(button("Keep editing")).click();
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals("draft", phone().getValue());
+        UI.getCurrent().navigate(AboutView.class);
+        test(button("Discard")).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+        assertTrue(phone().isEmpty());
+    }
+
+    @Test void emptyFormLeavesImmediately() {
+        test($(RouterLink.class).single()).click();
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse($(Dialog.class).exists());
+    }
+}
